@MainActor func transient_BoardLine_objectDisplay (
       _ self_mX1 : CanariLength,                  
       _ self_mY1 : CanariLength,                  
       _ self_mX2 : CanariLength,                  
       _ self_mY2 : CanariLength,                  
       _ self_mWidth : CanariLength,               
       _ self_mLayer : BoardLineLayer,             
       _ prefs_frontSideLegendColorForBoard : NSColor,
       _ prefs_backSideLegendColorForBoard : NSColor
) -> EBShape {
//--- START OF USER ZONE 2
      var bp = BezierPath ()
      bp.lineWidth = self_mWidth
      bp.lineCapStyle = .round
      bp.lineJoinStyle = .round
      let p1 = CanariPoint (x: self_mX1, y: self_mY1)
      let p2 = CanariPoint (x: self_mX2, y: self_mY2)
      bp.move (to: p1)
      bp.line (to: p2)
      let color : NSColor
      switch self_mLayer {
      case .legendFront :
        color = prefs_frontSideLegendColorForBoard
      case .legendBack :
        color = prefs_backSideLegendColorForBoard
      }
      return EBShape (stroke: [bp], color)
//--- END OF USER ZONE 2
}

